import React from 'react';

const Header: React.FC = () => (
  <header style={{ padding: '1rem', background: '#fff', color: '#222', display: 'flex', alignItems: 'center', boxShadow: '0 2px 8px #eee' }}>
    <img src="https://www.immunotec.com/images/logo-immunotec.svg" alt="Immunotec Logo" style={{ height: 40, marginRight: 16 }} />
    {/* Optionally, you can keep the text or remove it for just the logo */}
    {/* <h1 style={{ fontSize: 24, fontWeight: 700, margin: 0 }}>Immunotec</h1> */}
  </header>
);

export default Header;
